#!/usr/bin/env node
// Generates the app's types and its bundled schema set from the language-neutral schemas in contracts/obeya.
//   node scripts/gen-types.mjs            writes shared/generated/
//   node scripts/gen-types.mjs --check    exits 1 when the generated files are stale
// Options: --schemas <dir>  --out <dir>
import { readdirSync, readFileSync, writeFileSync, mkdirSync, existsSync } from 'node:fs'
import { join, dirname } from 'node:path'
import { fileURLToPath } from 'node:url'
import { compile } from 'json-schema-to-typescript'

const here = dirname(fileURLToPath(import.meta.url))
const args = process.argv.slice(2)
const opt = (name, fallback) => (args.includes(name) ? args[args.indexOf(name) + 1] : fallback)
const schemasDir = opt('--schemas', join(here, '..', '..', '..', 'contracts', 'obeya'))
const outDir = opt('--out', join(here, '..', 'shared', 'generated'))
const check = args.includes('--check')

const names = readdirSync(schemasDir).filter((f) => f.endsWith('.schema.json')).sort()
const schemas = Object.fromEntries(names.map((f) => [f, JSON.parse(readFileSync(join(schemasDir, f), 'utf8'))]))
const kinds = names.filter((f) => f !== 'provenance.schema.json')
const root = {
  title: 'ReadModel',
  type: 'object',
  additionalProperties: false,
  properties: Object.fromEntries(kinds.map((f) => [f.replace('.schema.json', ''), { $ref: f }])),
}
const types = await compile(root, 'ReadModel', {
  cwd: schemasDir + '/',
  bannerComment: '/* Generated by scripts/gen-types.mjs from contracts/obeya. Do not edit. */',
})
const files = {
  'read-model.d.ts': types,
  'schemas.json': JSON.stringify(schemas, null, 2) + '\n',
}

let stale = false
for (const [name, content] of Object.entries(files)) {
  const path = join(outDir, name)
  if (check) {
    if (!existsSync(path) || readFileSync(path, 'utf8') !== content) {
      console.error(`obeya: ${path} is stale; run npm run gen:types`)
      stale = true
    }
  } else {
    mkdirSync(outDir, { recursive: true })
    writeFileSync(path, content)
  }
}
process.exit(stale ? 1 : 0)
